/**
 * 智谱视觉识别模块
 * 使用智谱 GLM-4.6V-FlashX 模型进行图片识别
 */

(function() {
  'use strict';

  // API 配置
  const API_URL = 'https://open.bigmodel.cn/api/paas/v4/chat/completions';

  // 内置提示词模板列表（对应 prompts/*.txt 文件名）
  const PROMPT_TEMPLATE_NAMES = [
    '业务流程专家', '产品操作手册', '产品需求分析', '功能表格整理',
    '图片表格识别', '工时评估表格', '思维导图markdown', '技术分析专家',
    '招标参数撰写', '界面UIUX检查', '硬件说明书', '设计规范建议',
    '软件英文翻译', '软件问题分析',
    '医护人员培训材料', '医疗产品介绍撰写', '医疗合规需求分析',
    '医疗流程时序图', '医疗测试报告撰写', '医疗用户调研报告撰写',
    '医疗软件测试用例', '医疗项目计划书撰写', '医院业务流程梳理',
    '市场调研与机会发现',
    '操作步骤扩写', '图文综合分析'
  ];

  // 存储配置
  let zhipuConfig = {
    apiKey: '',
    enabled: false,
    defaultPrompt: '请详细描述这张图片的内容'
  };

  /**
   * 加载智谱配置
   */
  async function loadConfig() {
    return new Promise((resolve) => {
      chrome.storage.sync.get(['zhipuConfig'], (result) => {
        if (result.zhipuConfig) {
          zhipuConfig = { ...zhipuConfig, ...result.zhipuConfig };
        }
        resolve();
      });
    });
  }

  /**
   * 保存智谱配置
   */
  async function saveConfig(config) {
    return new Promise((resolve) => {
      zhipuConfig = { ...zhipuConfig, ...config };
      chrome.storage.sync.set({ zhipuConfig }, resolve);
    });
  }

  /**
   * 将图片转换为 Base64
   */
  function imageToBase64(imgDataUrl) {
    return imgDataUrl.split(',')[1];
  }

  /**
   * 调用智谱视觉识别 API
   */
  async function recognizeImage(imageDataUrl, customPrompt = null) {
    if (!zhipuConfig.apiKey) {
      throw new Error('请先在设置中配置智谱 API Key');
    }

    const prompt = customPrompt || zhipuConfig.defaultPrompt;
    const base64Image = imageToBase64(imageDataUrl);

    const requestBody = {
      model: 'GLM-4.6V-FlashX',
      messages: [
        {
          role: 'user',
          content: [
            {
              type: 'image_url',
              image_url: {
                url: `data:image/png;base64,${base64Image}`
              }
            },
            {
              type: 'text',
              text: prompt
            }
          ]
        }
      ],
      thinking: {
        type: 'enabled'
      }
    };

    try {
      const response = await fetch(API_URL, {
        method: 'POST',
        headers: {
          'Authorization': zhipuConfig.apiKey,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(requestBody)
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error?.message || `API 请求失败: ${response.status}`);
      }

      const data = await response.json();
      return data;
    } catch (error) {
      console.error('智谱识别错误:', error);
      throw error;
    }
  }

  /**
   * 纯文本 AI 撰写（不依赖图片）
   */
  async function recognizeText(prompt) {
    if (!zhipuConfig.apiKey) {
      throw new Error('请先在设置中配置智谱 API Key');
    }

    const requestBody = {
      model: 'glm-4-flash',
      messages: [
        {
          role: 'user',
          content: prompt
        }
      ]
    };

    try {
      const response = await fetch(API_URL, {
        method: 'POST',
        headers: {
          'Authorization': zhipuConfig.apiKey,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(requestBody)
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error?.message || `API 请求失败: ${response.status}`);
      }

      const data = await response.json();
      return data;
    } catch (error) {
      console.error('智谱文本撰写错误:', error);
      throw error;
    }
  }

  /**
   * 批量识别多张图片
   */
  async function recognizeImages(images, customPrompt = null, onProgress = null) {
    const results = [];

    for (let i = 0; i < images.length; i++) {
      try {
        const result = await recognizeImage(images[i], customPrompt);
        results.push({
          index: i,
          success: true,
          data: result
        });
      } catch (error) {
        results.push({
          index: i,
          success: false,
          error: error.message
        });
      }

      if (onProgress) {
        onProgress(i + 1, images.length, results[i]);
      }
    }

    return results;
  }

  /**
   * 显示识别结果的对话框
   */
  function showResultDialog(title, content, onClose = null) {
    // 移除已存在的对话框
    const existingDialog = document.getElementById('zhipuResultDialog');
    if (existingDialog) {
      existingDialog.remove();
    }

    const dialog = document.createElement('div');
    dialog.id = 'zhipuResultDialog';
    dialog.style.cssText = `
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background: rgba(0, 0, 0, 0.5);
      display: flex;
      align-items: center;
      justify-content: center;
      z-index: 10000;
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    `;

    const dialogContent = document.createElement('div');
    dialogContent.style.cssText = `
      background: var(--bg-secondary, #ffffff);
      color: var(--text-primary, #333);
      border-radius: 12px;
      padding: 24px;
      max-width: 600px;
      max-height: 80vh;
      width: 90%;
      overflow: auto;
      box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
    `;

    const headerHtml = `
      <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px;">
        <h3 style="margin: 0; font-size: 18px; font-weight: 600;">${title}</h3>
        <button id="closeZhipuDialog" style="
          background: none;
          border: none;
          font-size: 24px;
          cursor: pointer;
          color: var(--text-secondary, #666);
          padding: 4px 8px;
          line-height: 1;
        ">×</button>
      </div>
    `;

    const contentDiv = document.createElement('div');
    contentDiv.style.cssText = `
      white-space: pre-wrap;
      font-size: 14px;
      line-height: 1.6;
      color: var(--text-primary, #333);
    `;
    contentDiv.textContent = content;

    dialogContent.innerHTML = headerHtml;
    dialogContent.appendChild(contentDiv);
    dialog.appendChild(dialogContent);
    document.body.appendChild(dialog);

    // 事件绑定
    document.getElementById('closeZhipuDialog').addEventListener('click', () => {
      dialog.remove();
      if (onClose) onClose();
    });

    dialog.addEventListener('click', (e) => {
      if (e.target === dialog) {
        dialog.remove();
        if (onClose) onClose();
      }
    });
  }

  /**
   * 显示自定义提示词输入对话框
   */
  function showPromptDialog(defaultPrompt, onConfirm) {
    // 移除已存在的对话框
    const existingDialog = document.getElementById('zhipuPromptDialog');
    if (existingDialog) {
      existingDialog.remove();
    }

    const dialog = document.createElement('div');
    dialog.id = 'zhipuPromptDialog';
    dialog.style.cssText = `
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background: rgba(0, 0, 0, 0.5);
      display: flex;
      align-items: center;
      justify-content: center;
      z-index: 10000;
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    `;

    const dialogContent = document.createElement('div');
    dialogContent.style.cssText = `
      background: var(--bg-secondary, #ffffff);
      color: var(--text-primary, #333);
      border-radius: 16px;
      padding: 20px;
      max-width: 80%;
      width: 80%;
      box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
    `;

    // 构建模板选项 HTML
    const templateOptions = '<option value="">-- 选择内置提示词模板 --</option>' +
      PROMPT_TEMPLATE_NAMES.map(function(name) {
        return '<option value="' + name + '">' + name + '</option>';
      }).join('');

    dialogContent.innerHTML = `
      <h3 style="margin: 0 0 12px 0; font-size: 16px; font-weight: 600;">自定义识别提示词</h3>
      <div style="margin-bottom: 10px;">
        <select id="zhipuPromptTemplateSelect" style="
          width: 100%;
          padding: 8px 10px;
          border: 1px solid var(--border-color, #e1e5e9);
          border-radius: 10px;
          font-size: 14px;
          font-family: inherit;
          box-sizing: border-box;
          background: var(--input-bg, #ffffff);
          color: var(--input-text, #333);
          cursor: pointer;
          outline: none;
          appearance: auto;
        ">${templateOptions}</select>
      </div>
      <textarea id="zhipuCustomPrompt" style="
        width: 100%;
        min-height: 80px;
        padding: 10px;
        border: 1px solid var(--border-color, #e1e5e9);
        border-radius: 12px;
        font-size: 14px;
        resize: vertical;
        font-family: inherit;
        box-sizing: border-box;
        background: var(--input-bg, #ffffff);
        color: var(--input-text, #333);
      ">${defaultPrompt}</textarea>
      <div style="display: flex; gap: 8px; margin-top: 12px; justify-content: flex-end;">
        <button id="cancelPrompt" style="
          padding: 8px 16px;
          border: 1px solid var(--border-color, #e1e5e9);
          background: var(--bg-secondary, #fff);
          color: var(--text-primary, #333);
          border-radius: 20px;
          cursor: pointer;
          font-size: 14px;
          font-weight: 500;
        ">取消</button>
        <button id="confirmPrompt" style="
          padding: 8px 16px;
          border: none;
          background: #1a73e8;
          color: white;
          border-radius: 20px;
          cursor: pointer;
          font-size: 14px;
          font-weight: 500;
        ">确认识别</button>
      </div>
    `;

    dialog.appendChild(dialogContent);
    document.body.appendChild(dialog);

    // 自动聚焦到输入框
    setTimeout(() => {
      document.getElementById('zhipuCustomPrompt').focus();
    }, 100);

    // 事件绑定
    document.getElementById('cancelPrompt').addEventListener('click', () => {
      dialog.remove();
    });

    document.getElementById('confirmPrompt').addEventListener('click', () => {
      const prompt = document.getElementById('zhipuCustomPrompt').value.trim();
      dialog.remove();
      if (prompt && onConfirm) {
        onConfirm(prompt);
      }
    });

    dialog.addEventListener('click', (e) => {
      if (e.target === dialog) {
        dialog.remove();
      }
    });

    // 模板下拉框变更事件：选择后加载对应提示词文件内容填入文本域
    document.getElementById('zhipuPromptTemplateSelect').addEventListener('change', function() {
      const templateName = this.value;
      if (!templateName) return;
      const textarea = document.getElementById('zhipuCustomPrompt');
      textarea.value = '正在加载模板...';
      const url = chrome.runtime.getURL('prompts/' + encodeURIComponent(templateName) + '.txt');
      fetch(url)
        .then(function(response) { return response.text(); })
        .then(function(text) { textarea.value = text.trim(); })
        .catch(function(err) {
          textarea.value = '加载失败：' + templateName;
          console.error('[SnapScribe] 加载提示词模板失败:', err);
        });
    });
  }

  /**
   * 显示加载状态
   */
  function showLoadingDialog(message = '正在识别...') {
    const existingDialog = document.getElementById('zhipuLoadingDialog');
    if (existingDialog) {
      existingDialog.remove();
    }

    const dialog = document.createElement('div');
    dialog.id = 'zhipuLoadingDialog';
    dialog.style.cssText = `
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background: rgba(0, 0, 0, 0.5);
      display: flex;
      align-items: center;
      justify-content: center;
      z-index: 10001;
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    `;

    dialog.innerHTML = `
      <div style="
        background: var(--bg-secondary, #ffffff);
        color: var(--text-primary, #333);
        border-radius: 12px;
        padding: 32px;
        text-align: center;
        box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
      ">
        <div style="
          width: 48px;
          height: 48px;
          border: 4px solid var(--border-color, #e1e5e9);
          border-top-color: #667eea;
          border-radius: 50%;
          animation: zhipuSpin 1s linear infinite;
          margin: 0 auto 16px;
        "></div>
        <div id="zhipuLoadingText">${message}</div>
      </div>
      <style>
        @keyframes zhipuSpin {
          to { transform: rotate(360deg); }
        }
      </style>
    `;

    document.body.appendChild(dialog);
    return {
      updateMessage: (msg) => {
        const textEl = document.getElementById('zhipuLoadingText');
        if (textEl) textEl.textContent = msg;
      },
      close: () => dialog.remove()
    };
  }

  // 导出模块
  window.ZhipuVision = {
    loadConfig,
    saveConfig,
    recognizeImage,
    recognizeImages,
    recognizeText,
    showResultDialog,
    showPromptDialog,
    showLoadingDialog,
    getConfig: () => ({ ...zhipuConfig }),
    isConfigured: () => !!zhipuConfig.apiKey
  };
})();
